package com.cryptostrategy.platform.leaderboard.internal;import com.cryptostrategy.platform.evaluation.api.model.*;import com.cryptostrategy.platform.experiment.api.ExperimentId;import com.cryptostrategy.platform.leaderboard.api.model.LeaderboardRevision;import com.cryptostrategy.platform.leaderboard.api.port.in.ProjectLeaderboardUseCase;import com.cryptostrategy.platform.leaderboard.api.port.out.LeaderboardStore;import java.util.*;public final class LeaderboardService implements ProjectLeaderboardUseCase{private final LeaderboardStore store;private final TopKProjector projector=new TopKProjector();public LeaderboardService(LeaderboardStore store){this.store=Objects.requireNonNull(store);}@Override public LeaderboardRevision project(ExperimentId experiment,RankingVersion ranking,int topK,List<EvaluationResult> evaluations){var latest=store.latest(experiment);var candidate=projector.project(experiment,ranking,latest.map(r->r.revisionNumber()+1).orElse(1L),topK,evaluations);if(latest.isPresent()&&latest.get().fingerprint().equals(candidate.fingerprint()))return latest.get();return store.save(candidate);}}
